private fun done(c:Context,k:String)=c.getSharedPreferences("pathpilot_progress",Context.MODE_PRIVATE).getBoolean(k,false)
private fun setDone(c:Context,k:String,v:Boolean){c.getSharedPreferences("pathpilot_progress",Context.MODE_PRIVATE).edit().putBoolean(k,v).apply()}

@Composable fun PathPilotFullApp(viewModel:PathPilotViewModel){
 var tab by remember{mutableStateOf("home")}; var course by remember{mutableStateOf<Course?>(null)}; var project by remember{mutableStateOf<Project?>(null)}; var lesson by remember{mutableStateOf<Pair<String,String>?>(null)}; var gitOpen by remember{mutableStateOf(false)}; var mentorOpen by remember{mutableStateOf(false)}
 BackHandler(course!=null||project!=null||lesson!=null||gitOpen||mentorOpen){when{lesson!=null->lesson=null;course!=null->course=null;project!=null->project=null;gitOpen->gitOpen=false;mentorOpen->mentorOpen=false}}
 Surface(Modifier.fillMaxSize(),color=Bg){when{lesson!=null->Lesson(lesson!!.first,lesson!!.second){lesson=null};course!=null->CoursePage(course!!){name->lesson=course!!.name to name}{course=null};project!=null->ProjectPage(project!!){project=null};gitOpen->GitLab{gitOpen=false};mentorOpen->Mentor{mentorOpen=false};else->Shell(tab,{tab=it},{course=it},{project=it},{gitOpen=true},{mentorOpen=true})}}
}

@Composable private fun Shell(tab:String,setTab:(String)->Unit,openCourse:(Course)->Unit,openProject:(Project)->Unit,openGit:()->Unit,openMentor:()->Unit){
 Scaffold(containerColor=Bg,bottomBar={NavigationBar(containerColor=Color.White){Nav(Icons.Default.Home,"Home",tab=="home"){setTab("home")};Nav(Icons.Default.School,"Learn",tab=="learn"){setTab("learn")};Nav(Icons.Default.Build,"Build",tab=="build"){setTab("build")};Nav(Icons.Default.CalendarMonth,"College",tab=="college"){setTab("college")}}}){p->when(tab){"learn"->Learn(Modifier.padding(p),openCourse);"build"->Build(Modifier.padding(p),openProject,openGit,openMentor);"college"->College(Modifier.padding(p));else->Home(Modifier.padding(p),openCourse,openProject,openGit,openMentor)}}
}
