@Composable private fun Lesson(course:String,title:String,back:()->Unit){val ctx=LocalContext.current;var work by remember{mutableStateOf("")};var msg by remember{mutableStateOf("")};LazyColumn(contentPadding=PaddingValues(bottom=30.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{BackTop(title,course,back)};item{Block("Understand",concept(title))};item{Block("Your task",task(title))};item{Card(Modifier.padding(horizontal=16.dp).fillMaxWidth(),colors=CardDefaults.cardColors(Color.White),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(15.dp)){Text("YOUR WORK / EVIDENCE",color=Blue,fontSize=10.sp,fontWeight=FontWeight.Black);OutlinedTextField(work,{work=it},Modifier.fillMaxWidth().heightIn(min=170.dp).padding(top=8.dp),label={Text("Write code, command, explanation or evidence")});Button({if(work.trim().length>=8){setDone(ctx,"lesson:$course:$title",true);msg="✓ Completed. Evidence saved."}else msg="Add real evidence before submitting."},Modifier.fillMaxWidth().padding(top=8.dp)){Text("Submit & verify")};if(msg.isNotBlank())Text(msg,fontSize=11.sp,color=if(msg.startsWith("✓"))Green else Red,Modifier.padding(top=7.dp))}}};item{Block("Next", "Apply this skill in a project, then make a focused Git commit.")}}}
@Composable private fun Block(t:String,b:String){Card(Modifier.padding(horizontal=16.dp).fillMaxWidth(),colors=CardDefaults.cardColors(Color.White),shape=RoundedCornerShape(17.dp)){Column(Modifier.padding(15.dp)){Text(t,fontWeight=FontWeight.Black,color=Navy);Text(b,fontSize=12.sp,color=Gray,Modifier.padding(top=6.dp))}}}
private fun concept(s:String)=when{ s.contains("Branch",true)->"A branch isolates work from main so a feature can be reviewed safely.";s.contains("Commit",true)->"A commit is a small, reviewable checkpoint describing one logical change.";s.contains("HTTP",true)->"HTTP carries requests and responses using methods, URLs, headers, status codes and bodies.";s.contains("REST",true)->"REST designs predictable resource endpoints and uses HTTP semantics consistently.";s.contains("Testing",true)->"Tests are executable evidence that expected behaviour still works.";else->"Learn the concept, use it immediately, observe the result and record evidence."}
private fun task(s:String)=when{s.contains("Branch",true)->"Create feature/login-validation and explain why main should stay stable.";s.contains("Commit",true)->"Make one focused change and write a feat:, fix:, test: or docs: commit message.";s.contains("REST",true)->"Design GET /expenses and POST /expenses with request and response examples.";s.contains("Testing",true)->"Write one happy-path and one failure-path test.";s.contains("n8n",true)->"Create webhook → validation → CRM and include an error path.";else->"Create a tiny implementation, run/check it and explain what happened."}

