@Composable private fun GitLab(back:()->Unit){val ctx=LocalContext.current;var i by remember{mutableIntStateOf(0)};var input by remember{mutableStateOf("")};var msg by remember{mutableStateOf("")};val expected=git[i];LazyColumn(contentPadding=PaddingValues(bottom=30.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{BackTop("Git + GitHub Lab","Hands-on workflow",back)};item{Card(Modifier.padding(16.dp).fillMaxWidth(),colors=CardDefaults.cardColors(Navy),shape=RoundedCornerShape(20.dp)){Column(Modifier.padding(18.dp)){Text("MISSION ${i+1}/${git.size}",color=Color(0xFFBBD9FF),fontSize=10.sp,fontWeight=FontWeight.Black);Text(expected,color=Color.White,fontSize=20.sp,fontWeight=FontWeight.Black);Text("Do the action yourself. Then prove it.",color=Color(0xFFD8E0EF),fontSize=11.sp)}}};item{Card(Modifier.padding(horizontal=16.dp).fillMaxWidth(),colors=CardDefaults.cardColors(Color.White),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(15.dp)){Text("YOUR ANSWER",color=Blue,fontSize=10.sp,fontWeight=FontWeight.Black);OutlinedTextField(input,{input=it},Modifier.fillMaxWidth().padding(top=7.dp),label={Text(if(i==0)"What are the acceptance criteria?" else "Command / action")});Button({val ok=if(i==0)input.trim().length>=20 else input.trim().equals(expected,ignoreCase=true);msg=if(ok)"✓ Correct. Next step unlocked." else"✗ Not correct. Think about the purpose of this Git step.";if(ok){setDone(ctx,"git:$i",true);if(i<git.lastIndex){i++;input=""}}},Modifier.fillMaxWidth().padding(top=8.dp)){Text(if(i==git.lastIndex)"Finish" else"Check & continue")};if(msg.isNotBlank())Text(msg,fontSize=11.sp,color=if(msg.startsWith("✓"))Green else Red,Modifier.padding(top=7.dp))}}};item{Section("Workflow map")};items(git){x->Text("• $x",Modifier.padding(horizontal=20.dp),fontSize=11.sp,color=Gray)};item{Text("This lab teaches the real Git commands and workflow. It does not fake a GitHub commit. Real push/PR integration requires explicit GitHub authorization.",Modifier.padding(18.dp),fontSize=10.sp,color=Gray)}}}

